Name=$hshImage.Id+$hshExt; $hshFile=Join-Path $hshFolder $hshName; $hshResp=Invoke-WebRequest -Uri $hshImage.Url -Method Get -UseBasicParsing -TimeoutSec 20 -MaximumRedirection 5 -UserAgent 'Mozilla/5.0 (compatible; OwnerRequestedProductImages/1.0)' -OutFile $hshFile -PassThru -ErrorAction Stop; $hshLength=(Get-Item -LiteralPath $hshFile).Length; if($hshLength -lt 1 -or $hshLength -gt 4000000 -or ($hshBytes+$hshLength) -gt 26000000){throw 'Image size outside collection limit.'}; $hshContentType=[string]$hshResp.Headers['Content-Type']; if($hshContentType -and $hshContentType -notmatch '^image/') {throw ('Not an image: '+$hshContentType)}; $hshRec.status='downloaded_not_reviewed';$hshRec.file=$hshName;$hshRec.bytes=$hshLength;$hshRec.sha256=(Get-FileHash -LiteralPath $hshFile -Algorithm SHA256).Hash.ToLower();$hshBytes+=$hshLength;Write-Host ' Saved' -ForegroundColor Green; } catch {$hshRec.error=$_.Exception.Message; if($hshFile -and (Test-Path -LiteralPath $hshFile)){Remove-Item -LiteralPath $hshFile -Force}; Write-Host (' Failed: '+$hshRec.error) -ForegroundColor Yellow};$hshRecords+=[pscustomobject]$hshRec;}; $hshManifest=[ordered]@{format_version=1;kind='official_product_image_candidates';created_at=(Get-Date).ToUniversalTime().ToString('o');images=$hshRecords};[IO.File]::WriteAllText((Join-Path $hshFolder 'manifest.json'),($hshManifest|ConvertTo-Json -Depth 6),$hshUtf8);$hshZip=$hshFolder+'.zip';Compress-Archive -Path (Join-Path $hshFolder '*') -DestinationPath $hshZip -CompressionLevel Optimal -ErrorAction Stop; if(!(Test-Path -LiteralPath $hshZip -PathType Leaf)){throw 'ZIP creation failed.'};$hshGood=@($hshRecords|Where-Object {$_.status -eq 'downloaded_not_reviewed'}).Count;Write-Host ('Downloaded {0}/{1} images.' -f $hshGood,$hshImages.Count);Write-Host 'ZIP CREATED - upload this file:' -ForegroundColor Cyan;Write-Host $hshZip; } catch {Write-Host ('STOPPED: '+$_.Exception.Message) -ForegroundColor Red}; }
